#nullable enable
using JasperFx.Events;
using Marten;
using Spend.Concurrency;
using Spend.Contracts;
using Wolverine.Http;

namespace Spend.Slices.Spend;

/// <summary>
/// Releases part of a project's commitment, returning it to the department's available budget.
///
/// **THE CONTRAST WITH CommitSpend NEXT DOOR IS THE POINT OF HAVING BOTH SLICES.** The rule here — "a
/// project cannot release more than it committed" — is decided entirely by THIS project's own stream, so
/// it is an ordinary in-transaction invariant and <c>FetchForWriting</c>'s optimistic concurrency is a
/// real guard: two concurrent releases of the same project contend on that stream's version and one
/// loses. No tag, no guard row, no lock needed. Same model, one slice over, and the whole cross-stream
/// problem simply does not arise.
///
/// It still TAGS the event, and that is not inconsistency — the department boundary must stay correct, and
/// a release that was invisible to the tag query would make CommitSpend's fold read high for ever. The docs
/// are explicit that a plain tagged append also bumps the tag version, which is exactly what is wanted:
/// releasing money makes room, and a commit racing that release should re-read rather than use a stale total.
/// </summary>
public static class ReleaseCommitmentEndpoint
{
    public const string Route = "/projects/{projectId}/release";

    public const string ExceedsCommitment = "ReleaseExceedsCommitment";

    /// <remarks>
    /// STILL HAND-ROLLED, WITH A REASON — and the reason is the second of the two CLAUDE.md allows.
    ///
    /// Every other decider in this kit is now a pure function in Wolverine's aggregate handler workflow.
    /// This one is not, because the event it appends carries a **DCB tag**: it is built with
    /// <c>session.Events.BuildEvent(...)</c> and decorated with <c>WithTag(new DepartmentTag(...))</c>, and
    /// that tag is what maintains <c>mt_dcb_tag_version</c> — the side table the DCB arm's whole guarantee
    /// rests on. Building a tagged event needs the session, so the slice implementing a concurrency
    /// MECHANISM owns its transaction, exactly as <see cref="CommitSpendEndpoint"/> does.
    ///
    /// That is a narrow exemption, not a licence: it applies to the two slices that ARE the mechanism this
    /// folder measures. <c>SetBudgetEndpoint</c> and <c>OpenProjectEndpoint</c>, which decide nothing about
    /// concurrency, are both in the workflow.
    /// </remarks>
    [WolverinePost(Route)]
    public static async Task<IResult> Release(Guid projectId, ReleaseCommitment command, IDocumentSession session)
    {
        var stream = await session.Events.FetchForWriting<ReleaseCommitmentState>(projectId);
        var committed = stream.Aggregate?.Committed ?? 0m;

        if (command.Amount > committed)
            return Results.Problem(title: ExceedsCommitment, statusCode: StatusCodes.Status400BadRequest);

        var e = session.Events.BuildEvent(
            new CommitmentReleased(projectId, command.DepartmentId, command.Amount));
        e.WithTag(new DepartmentTag(command.DepartmentId));
        stream.AppendOne(e);

        return Results.NoContent();
    }
}
